from pricing import discounted_subtotal
from tax import apply_tax

def checkout(items, promo_percent=None):
    return apply_tax(discounted_subtotal(items, promo_percent))

def discounted_subtotal(items, promo_percent=None):
    subtotal = sum(unit_price * quantity for unit_price, quantity in items)
    discount = promo_percent or 10
    return subtotal * (1 - discount / 100)
